class DateFormatDetector : Detector(), SourceCodeScanner {

    override fun getApplicableUastTypes(): List<Class<out UElement>>? {
        return listOf(UCallExpression::class.java)
    }

    override fun createUastHandler(context: JavaContext): UElementHandler? {
        return object : UElementHandler() {
            override fun visitCallExpression(node: UCallExpression) {
                if (!node.isConstructor) return
                val classReference = node.classReference?.resolvedName ?: return
                if (classReference != "SimpleDateFormat") return
                // check qualified name
                val resolved = node.resolve() ?: return
                val containingClass = resolved.containingClass?.qualifiedName ?: return
                if (containingClass != "java.text.SimpleDateFormat") return

                val argCount = node.valueArgumentCount
                // SimpleDateFormat(String) and SimpleDateFormat(String, DateFormatSymbols)
                if (argCount == 1 || (argCount == 2 && isDateFormatSymbolsArgument(node, resolved))) {
                    context.report(
                        ISSUE,
                        node,
                        context.getLocation(node),
                        "To ensure consistent formatting, use the `SimpleDateFormat` constructor with an explicit `Locale` argument, or use `DateFormat.getDateInstance()` etc."
                    )
                }
            }
        }
    }

    private fun isDateFormatSymbolsArgument(node: UCallExpression, method: PsiMethod): Boolean { ... }

    companion object {
        val ISSUE = Issue.create(
            id = "SimpleDateFormat",
            briefDescription = "Implied locale in date format",
            explanation = """
                Almost all callers should use `getDateInstance()`, `getDateTimeInstance()`, or `getTimeInstance()` ...
                ...
            """.trimIndent(),
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(
                DateFormatDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}

